import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
  inOutEnvelope,
} from "../motion";

export const fps = 25;

// ============================================================
// OVERLAY LAYOUT
// This animation is composited OVER the talking-head shot (presenter
// centered, laptop front-left, bookshelf camera-right). All graphics are
// pushed into a LEFT panel so they never cover his face/body.
//
//  >>> PREVIEW_PRESENTER: set TRUE to scrub the composite in the preview,
//  >>> then set it back to FALSE before the transparent export (ProRes /
//  >>> QT-RLE) — otherwise the presenter still gets baked into the alpha.
// ============================================================
const PREVIEW_PRESENTER = false;

// Left-panel transform applied to the whole composition. Every scene centers
// its content full-frame, so scaling about center + nudging left moves the
// entire cluster into the camera-left zone while keeping each scene balanced.
const PANEL_SCALE = 0.48; // shrink to overlay size
const PANEL_TX = -28; // % of frame width — shift left, clear of his face
const PANEL_TY = -3; // % of frame height — slight lift to stay off the laptop

// ============================================================
// TIMING (25fps, NO OFFSET from transcript)
// 00:00.000 -> 00:00.959  => 0    -> 24   (1.0s) "The next time a content"
// 00:00.960 -> 00:02.439  => 24   -> 61   (1.5s) "shift happens in your space,"
// 00:02.440 -> 00:03.759  => 61   -> 94   (1.3s) "you see it in the data."
// 00:03.760 -> 00:04.999  => 94   -> 125  (1.2s) "Before you see it in your view"
// 00:05.000 -> 00:07.079  => 125  -> 177  (2.1s) "counts, you know what to film,"
// 00:07.080 -> 00:08.439  => 177  -> 211  (1.4s) "what formats are winning,"
// 00:08.440 -> 00:10.039  => 211  -> 251  (1.6s) "and which competitor proved it."
// Total: 251 frames
// ============================================================

const SCENE_1_DUR = 61;   // "content shift happens"
const SCENE_2_DUR = 33;   // "you see it in the data"
const SCENE_3_DUR = 83;   // "before view counts / you know what to film"
const SCENE_4_DUR = 40;   // "what formats are winning"
const SCENE_5_DUR = 40;   // "which competitor proved it"

const TRANSITION = 4;

export const durationInFrames =
  SCENE_1_DUR + SCENE_2_DUR + SCENE_3_DUR + SCENE_4_DUR + SCENE_5_DUR;

const COLORS = {
  bg: "#161718",
  card: "#1d1e1f",
  border: "#3d3f43",
  text: "#f4f4f5",
  textMuted: "#bfc1c5",
  textSubtle: "#8c93a8",
  orange: "#F86606",
  orangeDeep: "#FF4800",
  orangeTint: "rgba(248,102,6,0.16)",
};

// ============================================================
// SCENE 1: Content shift — a feed reshuffles
// 0 -> 94 frames (0:00 -> 0:03.76)
// "The next time a content shift happens in your space, you see it in the data."
// A feed of content rows sits calm, then at ~frame 24 ("shift happens") the
// hero row leaps to the top, lights orange and tags NEW, then holds.
// ============================================================
const Scene1ContentShift: React.FC = () => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const cardIn = springIn(frame, fps, 1, "LIQUID");
  const cardDriftY = ambientDrift(frame, 2, 90, "feed-card");

  const cardW = width * 0.58;
  const cardH = height * 0.5;
  const padX = cardW * 0.07;
  const padY = cardH * 0.09;
  const innerW = cardW - padX * 2;
  const innerH = cardH - padY * 2;

  const COUNT = 5;
  const rowGap = innerH * 0.05;
  const rowH = (innerH - rowGap * (COUNT - 1)) / COUNT;
  const rowPitch = rowH + rowGap;

  // The "shift" fires when "shift happens" is said (~frame 24).
  const shift = spring({ frame: frame - 24, fps, config: SPRINGS.LIQUID });
  const HERO = 3; // originally the 4th row — leaps to the top
  const toSlot = (i: number) => (i === HERO ? 0 : i < HERO ? i + 1 : i);
  const items = Array.from({ length: COUNT });

  return (
    <AbsoluteFill>
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            width: cardW,
            height: cardH,
            backgroundColor: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: 28,
            position: "relative",
            opacity: cardIn,
            transform: `translateY(${interpolate(cardIn, [0, 1], [40, 0])}px) translateY(${cardDriftY}px) scale(${interpolate(cardIn, [0, 1], [0.94, 1])})`,
            boxShadow: "0 24px 64px rgba(0,0,0,0.4)",
            overflow: "hidden",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: padX,
              top: padY,
              width: innerW,
              height: innerH,
            }}
          >
            {items.map((_, i) => {
              const isHero = i === HERO;
              const enterIn = staggeredSpring(frame, fps, i, 2, 1.5, "SNAPPY");
              const slot = interpolate(shift, [0, 1], [i, toSlot(i)]);
              const y = slot * rowPitch;
              const heat = isHero ? shift : 0;

              return (
                <div
                  key={i}
                  style={{
                    position: "absolute",
                    left: 0,
                    top: y,
                    width: "100%",
                    height: rowH,
                    display: "flex",
                    alignItems: "center",
                    gap: rowH * 0.3,
                    padding: `0 ${rowH * 0.3}px`,
                    boxSizing: "border-box",
                    borderRadius: rowH * 0.22,
                    backgroundColor: isHero
                      ? `rgba(248,102,6,${0.1 + 0.07 * heat})`
                      : "rgba(255,255,255,0.04)",
                    border: `${isHero ? 1 + heat : 1}px solid ${isHero && heat > 0.15 ? COLORS.orange : COLORS.border}`,
                    opacity: enterIn,
                    transform: `translateX(${interpolate(enterIn, [0, 1], [-30, 0])}px)`,
                    boxShadow:
                      isHero && heat > 0.2
                        ? `0 0 ${40 * heat}px rgba(248,102,6,${0.28 * heat})`
                        : "none",
                    zIndex: isHero ? 10 : 1,
                  }}
                >
                  {/* Thumbnail */}
                  <div
                    style={{
                      width: rowH * 0.62,
                      height: rowH * 0.62,
                      borderRadius: rowH * 0.16,
                      flexShrink: 0,
                      backgroundColor: isHero
                        ? COLORS.orange
                        : "rgba(255,255,255,0.10)",
                      opacity: isHero ? 0.4 + 0.6 * heat : 1,
                    }}
                  />

                  {/* Title + subtitle skeleton */}
                  <div
                    style={{
                      flex: 1,
                      display: "flex",
                      flexDirection: "column",
                      gap: rowH * 0.18,
                    }}
                  >
                    <div
                      style={{
                        width: isHero ? "72%" : `${55 + ((i * 13) % 28)}%`,
                        height: rowH * 0.18,
                        borderRadius: rowH * 0.09,
                        backgroundColor: isHero
                          ? `rgba(255,255,255,${0.18 + 0.12 * heat})`
                          : "rgba(255,255,255,0.14)",
                      }}
                    />
                    <div
                      style={{
                        width: isHero ? "44%" : `${30 + ((i * 7) % 20)}%`,
                        height: rowH * 0.13,
                        borderRadius: rowH * 0.07,
                        backgroundColor: "rgba(255,255,255,0.08)",
                      }}
                    />
                  </div>

                  {/* Trailing: NEW ▲ badge on hero, metric chip otherwise */}
                  {isHero ? (
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: rowH * 0.14,
                        flexShrink: 0,
                        opacity: heat,
                        transform: `scale(${0.6 + 0.4 * heat})`,
                      }}
                    >
                      <span
                        style={{
                          fontFamily: "'GT Walsheim', Inter, sans-serif",
                          fontWeight: 600,
                          fontSize: rowH * 0.26,
                          color: COLORS.orange,
                          letterSpacing: "0.08em",
                        }}
                      >
                        NEW
                      </span>
                      <span
                        style={{
                          fontSize: rowH * 0.32,
                          color: COLORS.orange,
                          lineHeight: 1,
                        }}
                      >
                        ▲
                      </span>
                    </div>
                  ) : (
                    <div
                      style={{
                        width: rowH * 0.9,
                        height: rowH * 0.16,
                        borderRadius: rowH * 0.08,
                        flexShrink: 0,
                        backgroundColor: "rgba(255,255,255,0.08)",
                      }}
                    />
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ============================================================
// SCENE 3: "Before view counts" — counter ticking up but framed as "early signal"
// 94 -> 177 frames (0:03.76 -> 0:07.08)
// Two stacked metric cards: one "view count" lagging, one "signal" leading
// Then around frame ~125 (when "you know what to film" hits), pivots
// ============================================================
const Scene3EarlySignal: React.FC = () => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const localFrame = frame; // relative to scene start (TransitionSeries handles this)

  const card1In = springIn(localFrame, fps, 2, "LIQUID");
  const card2In = springIn(localFrame, fps, 10, "LIQUID");

  // Card 1 (Views) — counts up slowly, lags behind
  const viewsProgress = interpolate(localFrame, [4, 70], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const viewsCount = Math.round(interpolate(viewsProgress, [0, 1], [0, 1247]));

  // Card 2 (Signal) — spikes early & decisively around frame ~14
  const signalProgress = springIn(localFrame, fps, 14, "LIQUID");
  const signalCount = Math.round(interpolate(signalProgress, [0, 1], [0, 87]));

  const drift1 = ambientDrift(localFrame, 2, 100, "card-a");
  const drift2 = ambientDrift(localFrame, 2, 110, "card-b");

  // Around frame ~31 (= overall frame ~125, "Before you see it in your view counts")
  // emphasize signal card with a glowing border pulse
  const emphasisStart = 31;
  const emphasis = interpolate(
    localFrame,
    [emphasisStart, emphasisStart + 12],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const cardW = width * 0.34;
  const cardH = height * 0.32;

  // Mini sparkline data
  const sparkData1 = [0.3, 0.32, 0.34, 0.31, 0.35, 0.38, 0.4, 0.42, 0.44, 0.46];
  const sparkData2 = [0.2, 0.22, 0.28, 0.4, 0.55, 0.68, 0.78, 0.85, 0.9, 0.94];

  const Sparkline = ({
    data,
    color,
    progress,
  }: {
    data: number[];
    color: string;
    progress: number;
  }) => {
    const w = cardW * 0.78;
    const h = cardH * 0.22;
    const visible = Math.max(2, Math.floor(progress * data.length));
    const pts = data
      .slice(0, visible)
      .map((v, i) => {
        const x = (i / (data.length - 1)) * w;
        const y = (1 - v) * h;
        return `${i === 0 ? "M" : "L"} ${x} ${y}`;
      })
      .join(" ");
    return (
      <svg width={w} height={h}>
        <path
          d={pts}
          stroke={color}
          strokeWidth={3}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    );
  };

  return (
    <AbsoluteFill>
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "center",
          gap: width * 0.04,
        }}
      >
        {/* LEFT CARD — "Views" lagging */}
        <div
          style={{
            width: cardW,
            height: cardH,
            backgroundColor: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: 24,
            padding: "36px 40px",
            display: "flex",
            flexDirection: "column",
            justifyContent: "space-between",
            opacity: card1In * (1 - emphasis * 0.4),
            transform: `translateY(${interpolate(card1In, [0, 1], [40, 0])}px) translateY(${drift1}px) scale(${interpolate(card1In, [0, 1], [0.94, 1 - emphasis * 0.03])})`,
            boxShadow: "0 24px 64px rgba(0,0,0,0.4)",
            filter: `blur(${emphasis * 1.5}px)`,
          }}
        >
          {/* Top: dot + label */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 14,
            }}
          >
            <div
              style={{
                width: 12,
                height: 12,
                borderRadius: 6,
                backgroundColor: COLORS.textSubtle,
              }}
            />
            <div
              style={{
                width: 80,
                height: 10,
                backgroundColor: "rgba(255,255,255,0.12)",
                borderRadius: 5,
              }}
            />
          </div>

          {/* Number */}
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontWeight: 600,
              fontSize: height * 0.085,
              color: COLORS.textMuted,
              letterSpacing: "-0.03em",
              lineHeight: 0.9,
              fontVariantNumeric: "tabular-nums",
            }}
          >
            {viewsCount.toLocaleString()}
          </div>

          {/* Sparkline */}
          <Sparkline
            data={sparkData1}
            color={COLORS.textSubtle}
            progress={viewsProgress}
          />
        </div>

        {/* RIGHT CARD — "Signal" leading */}
        <div
          style={{
            width: cardW,
            height: cardH,
            backgroundColor: COLORS.card,
            border: `${1 + emphasis * 1}px solid ${emphasis > 0 ? COLORS.orange : COLORS.border}`,
            borderRadius: 24,
            padding: "36px 40px",
            display: "flex",
            flexDirection: "column",
            justifyContent: "space-between",
            opacity: card2In,
            transform: `translateY(${interpolate(card2In, [0, 1], [40, 0])}px) translateY(${drift2}px) scale(${interpolate(card2In, [0, 1], [0.94, 1 + emphasis * 0.04])})`,
            boxShadow: `0 24px 64px rgba(0,0,0,0.4)${emphasis > 0 ? `, 0 0 ${40 * emphasis}px rgba(248,102,6,${0.25 * emphasis})` : ""}`,
          }}
        >
          {/* Top: orange dot + label */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 14,
            }}
          >
            <div
              style={{
                width: 12,
                height: 12,
                borderRadius: 6,
                backgroundColor: COLORS.orange,
                boxShadow: `0 0 ${8 + Math.sin(localFrame * 0.3) * 6}px ${COLORS.orange}`,
              }}
            />
            <div
              style={{
                width: 100,
                height: 10,
                backgroundColor: COLORS.orangeTint,
                borderRadius: 5,
              }}
            />
          </div>

          {/* Number with trend arrow */}
          <div
            style={{
              display: "flex",
              alignItems: "baseline",
              gap: 16,
            }}
          >
            <div
              style={{
                fontFamily: "'GT Walsheim', Inter, sans-serif",
                fontWeight: 600,
                fontSize: height * 0.105,
                color: COLORS.text,
                letterSpacing: "-0.03em",
                lineHeight: 0.9,
                fontVariantNumeric: "tabular-nums",
              }}
            >
              {signalCount}
            </div>
            <div
              style={{
                fontFamily: "'GT Walsheim', Inter, sans-serif",
                fontWeight: 600,
                fontSize: height * 0.03,
                color: COLORS.orange,
                opacity: signalProgress,
              }}
            >
              ▲
            </div>
          </div>

          {/* Sparkline */}
          <Sparkline
            data={sparkData2}
            color={COLORS.orange}
            progress={signalProgress}
          />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ============================================================
// SCENE 4: "What formats are winning"
// 177 -> 217 frames (0:07.08 -> 0:08.44)
// Horizontal bar race: 4 format bars, top one extends with a checkmark
// ============================================================
const Scene4FormatsWinning: React.FC = () => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const FORMATS = [
    { value: 92, winning: true },
    { value: 64, winning: false },
    { value: 48, winning: false },
    { value: 31, winning: false },
  ];

  const cardW = width * 0.6;
  const cardH = height * 0.5;

  const containerIn = springIn(frame, fps, 1, "LIQUID");
  const drift = ambientDrift(frame, 1.5, 100, "formats");

  return (
    <AbsoluteFill>
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            width: cardW,
            height: cardH,
            backgroundColor: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: 28,
            padding: "48px 56px",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            gap: cardH * 0.06,
            opacity: containerIn,
            transform: `translateY(${interpolate(containerIn, [0, 1], [40, 0])}px) translateY(${drift}px) scale(${interpolate(containerIn, [0, 1], [0.94, 1])})`,
            boxShadow: "0 24px 64px rgba(0,0,0,0.4)",
          }}
        >
          {FORMATS.map((f, i) => {
            const rowIn = staggeredSpring(
              frame,
              fps,
              i,
              4,
              4,
              "LIQUID"
            );
            const barProgress = staggeredSpring(
              frame,
              fps,
              i,
              8,
              4,
              "LIQUID"
            );

            const barColor = f.winning ? COLORS.orange : COLORS.textSubtle;
            const trackBg = "rgba(255,255,255,0.06)";

            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 24,
                  opacity: rowIn,
                  transform: `translateX(${interpolate(rowIn, [0, 1], [-30, 0])}px)`,
                }}
              >
                {/* Rank dot */}
                <div
                  style={{
                    width: height * 0.04,
                    height: height * 0.04,
                    borderRadius: "50%",
                    backgroundColor: f.winning ? COLORS.orange : COLORS.card,
                    border: `1.5px solid ${f.winning ? COLORS.orange : COLORS.border}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    flexShrink: 0,
                  }}
                >
                  {f.winning && (
                    <svg
                      width={height * 0.022}
                      height={height * 0.022}
                      viewBox="0 0 24 24"
                    >
                      <path
                        d="M5 12.5 L10 17.5 L19 7"
                        stroke={COLORS.text}
                        strokeWidth={3.5}
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        fill="none"
                      />
                    </svg>
                  )}
                </div>

                {/* Track + bar */}
                <div
                  style={{
                    flex: 1,
                    height: height * 0.045,
                    backgroundColor: trackBg,
                    borderRadius: height * 0.025,
                    overflow: "hidden",
                  }}
                >
                  <div
                    style={{
                      width: `${f.value * barProgress}%`,
                      height: "100%",
                      backgroundColor: barColor,
                      borderRadius: height * 0.025,
                    }}
                  />
                </div>

                {/* Value */}
                <div
                  style={{
                    width: height * 0.08,
                    fontFamily: "'GT Walsheim', Inter, sans-serif",
                    fontWeight: 600,
                    fontSize: height * 0.032,
                    color: f.winning ? COLORS.orange : COLORS.textSubtle,
                    fontVariantNumeric: "tabular-nums",
                    textAlign: "right",
                    opacity: barProgress,
                  }}
                >
                  {Math.round(f.value * barProgress)}%
                </div>
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ============================================================
// SCENE 5: "Which competitor proved it"
// 217 -> 251 frames (0:08.44 -> 0:10.04)
// Grid of competitor cards; one card highlights/zooms with orange ring
// ============================================================
const Scene5CompetitorProved: React.FC = () => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const COMPETITORS = [
    { winner: false },
    { winner: false },
    { winner: true }, // highlighted one
    { winner: false },
    { winner: false },
    { winner: false },
  ];

  const gridW = width * 0.7;
  const gridH = height * 0.55;
  const gap = 28;
  const cols = 3;
  const rows = 2;
  const cardW = (gridW - gap * (cols - 1)) / cols;
  const cardH = (gridH - gap * (rows - 1)) / rows;

  const winnerEmphasis = springIn(frame, fps, 14, "LIQUID");

  return (
    <AbsoluteFill>
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            width: gridW,
            height: gridH,
            display: "grid",
            gridTemplateColumns: `repeat(${cols}, 1fr)`,
            gridTemplateRows: `repeat(${rows}, 1fr)`,
            gap,
          }}
        >
          {COMPETITORS.map((c, i) => {
            const cardIn = staggeredSpring(
              frame,
              fps,
              i,
              2,
              3,
              "LIQUID"
            );
            const driftY = ambientDrift(frame, 1.5, 90 + i * 13, `comp-${i}`);

            const isWinner = c.winner;
            const dim = !isWinner ? winnerEmphasis * 0.55 : 0;
            const scale = isWinner
              ? interpolate(cardIn, [0, 1], [0.94, 1]) +
                winnerEmphasis * 0.05
              : interpolate(cardIn, [0, 1], [0.94, 1]) - winnerEmphasis * 0.02;

            return (
              <div
                key={i}
                style={{
                  position: "relative",
                  width: cardW,
                  height: cardH,
                  backgroundColor: COLORS.card,
                  border: `${isWinner ? 2 : 1}px solid ${isWinner && winnerEmphasis > 0.3 ? COLORS.orange : COLORS.border}`,
                  borderRadius: 20,
                  padding: 28,
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "space-between",
                  opacity: cardIn * (1 - dim),
                  transform: `translateY(${interpolate(cardIn, [0, 1], [30, 0])}px) translateY(${driftY}px) scale(${scale})`,
                  filter: `blur(${dim * 2}px)`,
                  boxShadow: isWinner
                    ? `0 24px 64px rgba(0,0,0,0.4), 0 0 ${40 * winnerEmphasis}px rgba(248,102,6,${0.3 * winnerEmphasis})`
                    : "0 12px 32px rgba(0,0,0,0.3)",
                }}
              >
                {/* Top row: logo placeholder + status dot */}
                <div
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                  }}
                >
                  <div
                    style={{
                      width: cardW * 0.18,
                      height: cardW * 0.18,
                      borderRadius: 12,
                      backgroundColor: isWinner ? COLORS.orangeTint : "rgba(255,255,255,0.08)",
                      border: `1px solid ${isWinner ? COLORS.orange : COLORS.border}`,
                    }}
                  />
                  {isWinner && winnerEmphasis > 0.2 && (
                    <div
                      style={{
                        width: 14,
                        height: 14,
                        borderRadius: 7,
                        backgroundColor: COLORS.orange,
                        boxShadow: `0 0 ${8 + Math.sin(frame * 0.3) * 6}px ${COLORS.orange}`,
                      }}
                    />
                  )}
                </div>

                {/* Bottom: skeleton lines */}
                <div
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    gap: 10,
                  }}
                >
                  <div
                    style={{
                      width: "70%",
                      height: 12,
                      backgroundColor: isWinner
                        ? "rgba(255,255,255,0.18)"
                        : "rgba(255,255,255,0.08)",
                      borderRadius: 6,
                    }}
                  />
                  <div
                    style={{
                      width: "45%",
                      height: 8,
                      backgroundColor: isWinner
                        ? "rgba(255,255,255,0.12)"
                        : "rgba(255,255,255,0.06)",
                      borderRadius: 4,
                    }}
                  />
                </div>

                {/* Winner checkmark overlay */}
                {isWinner && (
                  <div
                    style={{
                      position: "absolute",
                      right: 20,
                      bottom: 20,
                      width: 56,
                      height: 56,
                      borderRadius: 28,
                      backgroundColor: COLORS.orange,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      opacity: winnerEmphasis,
                      transform: `scale(${winnerEmphasis})`,
                      boxShadow: `0 8px 24px rgba(248,102,6,0.4)`,
                    }}
                  >
                    <svg width={32} height={32} viewBox="0 0 24 24">
                      <path
                        d="M5 12.5 L10 17.5 L19 7"
                        stroke={COLORS.text}
                        strokeWidth={3.5}
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        fill="none"
                      />
                    </svg>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ============================================================
// EXIT WRAP — gives every scene a real exit instead of a hard cut.
// In the last frames the graphic recedes: scales down, drifts up, and
// fades to transparent (revealing the presenter, never to black).
// `dur` is the frame at which the exit completes — for scenes 1-4 that's
// SCENE_DUR (just before the crossfade); for scene 5 it's the end.
// ============================================================
const ExitWrap: React.FC<{ dur: number; children: React.ReactNode }> = ({
  dur,
  children,
}) => {
  const frame = useCurrentFrame();
  const EXIT = Math.min(15, Math.round(dur * 0.3));
  const raw = interpolate(frame, [dur - EXIT, dur], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const e = raw * raw * (3 - 2 * raw); // smoothstep ease

  return (
    <AbsoluteFill
      style={{
        opacity: 1 - e,
        transform: `translateY(${e * -4}%) scale(${1 - e * 0.08})`,
      }}
    >
      {children}
    </AbsoluteFill>
  );
};

